using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
namespace CodexMeter {
public sealed class UpdateManifest {public string version;public Dictionary<string,string> files;}
public sealed class UpdateJob {public string target,stage,version,profile;public int processId;}
public static class UpdatePackage {
    public static readonly string[] RuntimeFiles={"CodexMeter.exe","CodexMeter.exe.config","CodexMeter.ico","CodexMeter.Updater.exe","icon-67-512.webp","libwebp.dll","libsharpyuv.dll","vcruntime140.dll","WebP-LICENSE.txt","WebP-PATENTS.txt","ThirdParty.txt","README.txt","SkinGuide.md","update-source.json"};
    public static string Hash(string path){using(var sha=SHA256.Create())using(var input=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
    public static Version VersionOf(string tag){Version v;if(!Version.TryParse((tag??"").TrimStart('v','V'),out v))throw new Exception("Invalid release version");return new Version(v.Major,v.Minor,Math.Max(0,v.Build),Math.Max(0,v.Revision));}
    public static bool Allowed(string name){return RuntimeFiles.Contains(name,StringComparer.OrdinalIgnoreCase)||Regex.IsMatch(name??"","^skins/[a-z0-9-]+\\.(webp|json)$",RegexOptions.IgnoreCase);}
    public static UpdateManifest Validate(string stage,string expected){var manifest=new JavaScriptSerializer().Deserialize<UpdateManifest>(File.ReadAllText(Path.Combine(stage,"update-manifest.json")));if(manifest==null||VersionOf(manifest.version)!=VersionOf(expected)||manifest.files==null||manifest.files.Count>100||manifest.files.Keys.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=manifest.files.Count)throw new Exception("Invalid update manifest");foreach(string required in RuntimeFiles.Concat(new[]{"skins/skins.json"}))if(!manifest.files.ContainsKey(required))throw new Exception("Missing update file: "+required);foreach(var pair in manifest.files){if(!Allowed(pair.Key)||!Regex.IsMatch(pair.Value??"","^[a-fA-F0-9]{64}$")||!string.Equals(Hash(Path.Combine(stage,pair.Key.Replace('/',Path.DirectorySeparatorChar))),pair.Value,StringComparison.OrdinalIgnoreCase))throw new Exception("Invalid update file: "+pair.Key);}return manifest;}
    public static UpdateManifest Extract(string zip,string stage,string version){Directory.CreateDirectory(stage);using(var archive=ZipFile.OpenRead(zip)){var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;if(archive.Entries.Count>101)throw new Exception("Update archive too large");foreach(var entry in archive.Entries){string name=entry.FullName.Replace('\\','/');if(!names.Add(name)||name!="update-manifest.json"&&!Allowed(name)||entry.Length>32*1024*1024||(total+=entry.Length)>100*1024*1024)throw new Exception("Invalid archive entry: "+name);string target=Path.Combine(stage,name.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(target));entry.ExtractToFile(target,false);}}var result=Validate(stage,version);if(Directory.GetFiles(stage,"*",SearchOption.AllDirectories).Length!=result.files.Count+1)throw new Exception("Unexpected update files");return result;}
    public static void Apply(string stage,string target,string version){target=Path.GetFullPath(target);if(!File.Exists(Path.Combine(target,"CodexMeter.exe"))||Path.GetPathRoot(target).TrimEnd('\\')==target.TrimEnd('\\'))throw new Exception("Invalid application folder");var manifest=Validate(stage,version);string backup=Path.Combine(Path.GetDirectoryName(stage),"backup");Directory.CreateDirectory(backup);var copied=new List<string>();var existed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);try{foreach(string name in manifest.files.Keys){string dst=Path.Combine(target,name),old=Path.Combine(backup,name);if(File.Exists(dst)){Directory.CreateDirectory(Path.GetDirectoryName(old));File.Copy(dst,old,true);existed.Add(name);}copied.Add(name);Directory.CreateDirectory(Path.GetDirectoryName(dst));File.Copy(Path.Combine(stage,name),dst,true);}foreach(var pair in manifest.files)if(Hash(Path.Combine(target,pair.Key))!=pair.Value.ToLowerInvariant())throw new Exception("Installed file verification failed");}catch{foreach(string name in copied.AsEnumerable().Reverse()){string dst=Path.Combine(target,name);if(existed.Contains(name)){string old=Path.Combine(backup,name);if(!File.Exists(dst)||Hash(dst)!=Hash(old))File.Copy(old,dst,true);}else if(File.Exists(dst))File.Delete(dst);}throw;}}
}
}
